mapper.select:
SELECT FROM lab_milestone m LEFT JOIN lab_task t ON t.milestone_id = m.id AND t.project_id = m.project_id WHERE m.project_id = #{projectId}
AND m.status = #{status}
GROUP BY m.id, m.project_id, m.name, m.description, m.status, m.start_date, m.end_date, m.sort_order, m.create_time, m.update_time ORDER BY m.sort_order ASC, m.id ASC

mapper.update:
UPDATE lab_milestone
SET status = #{targetStatus}, update_time = #{updateTime}
WHERE project_id = #{projectId}
  AND id = #{milestoneId}
  AND status = #{currentStatus}
